  const id = Number(projectId);

  return (
    <section data-testid="project-detail-page">
      <h1>Project</h1>
      <ProjectDetail.Slot projectId={id} />
      <InvoiceForm projectId={id} />
      <InvoiceList projectId={id} />
    </section>
  );
}
